RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_384 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.embedding_model = p_embedding_model AND ct.tenant_id = p_tenant AND ct.collection <> p_collection AND ct.collection <> ALL (ARRAY( SELECT cc.name FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant AND cc.embedding_model = p_embedding_model AND COALESCE(cc.superseded_by, '') <> '')) AND ct.embedding_384 IS NOT NULL ORDER BY ct.embedding_384 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( -- RDR-225: embedding_model is the chunk's own (it is part of the four-column chunk foreign key). INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection, embedding_model, source_collection_id) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection, n.m_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = current_setting('nexus.tenant', true) AND cc.name = p_collection) FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, -- the model moves with the source collection: the pair is one chunk reference. embedding_model = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.embedding_model ELSE ta.embedding_model END, -- the id moves with the name; a row the name did not move keeps its id, or takes the registry's if it has none source_collection_id = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection_id ELSE COALESCE(ta.source_collection_id, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = current_setting('nexus.tenant', true) AND cc.name = ta.source_collection)) END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, c.embedding_model AS m_model, ct.topic_id AS m_topic_id, (1 - (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.embedding_model = p_embedding_model AND ct.tenant_id = p_tenant AND ct.collection = p_collection AND ct.embedding_384 IS NOT NULL WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = p_collection AND c.embedding_384 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_384 OPERATOR(nexus.<=>) ct.embedding_384) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection, embedding_model, source_collection_id) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection, n.m_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = current_setting('nexus.tenant', true) AND cc.name = p_collection) FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $function$;

