CREATE OR REPLACE FUNCTION nexus.assign_from_chashes_768(p_collection text, p_chashes text[], p_cross_collection boolean, p_embedding_model text, p_tenant text) RETURNS TABLE(chash text, topic_id bigint, similarity double precision) LANGUAGE plpgsql SET plan_cache_mode = force_custom_plan AS $function$ #variable_conflict use_column DECLARE v_cid bigint; BEGIN SELECT cc.collection_id INTO v_cid FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant AND cc.name = p_collection; IF p_cross_collection THEN IF NOT EXISTS ( SELECT 1 FROM nexus.catalog_collections WHERE tenant_id = current_setting('nexus.tenant', true) AND name = p_collection AND embedding_model = p_embedding_model ) THEN RAISE EXCEPTION 'assign_from_chashes_768: collection % is not registered for tenant % -- register it first via POST /v1/catalog/collections/upsert', p_collection, current_setting('nexus.tenant', true) USING ERRCODE = 'foreign_key_violation'; END IF;
-- nexus-f3yxx: the LATERAL's recall settings, transaction-local. -- NOT a function-level SET clause: CREATE FUNCTION ... SET hnsw.* -- fails with 'permission denied to set parameter' for a -- non-superuser migration role when pgvector's library is not yet -- loaded in that session (hnsw.* is then an unknown placeholder), -- which is every production boot (candidate-migration leg, -- 2026-09-25). set_config is allowed to any role. is_local=true -- scopes it to this transaction, which since the rework is the -- cross pass alone. PERFORM set_config('hnsw.iterative_scan', 'strict_order', true); PERFORM set_config('hnsw.ef_search', '400', true);
-- nexus-swam7: pin the ACCESS PATH itself, not just the ANN recall -- settings. At ef_search=400 the planner's own cost model prefers a -- per-chunk Seq Scan + top-N Sort over taxonomy_centroids until -- ~8,000 centroids/dim (T2 nexus/p02-hnsw-incremental-recall- -- 2026-09-25); below that, this pin is what makes the "measured -- equal to exact at ef400" claim (taxonomy-018's header) actually -- true, by forcing the HNSW index scan the recall claim assumes. -- Legal as a function-level SET (these are core GUCs, unlike -- hnsw.*), but kept as set_config for consistency with the two -- calls above -- see this changeset's own header for the full -- reasoning and the measurement that verified each pin's effect. PERFORM set_config('enable_seqscan', 'off', true); PERFORM set_config('enable_sort', 'off', true);
RETURN QUERY WITH batch AS ( SELECT c.chash AS b_chash, c.embedding_768 AS b_emb, c.embedding_model AS b_model FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND (c.collection_id = v_cid OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND c.embedding_768 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ), nearest AS ( SELECT encode(b.b_chash, 'hex') AS m_chash, b.b_chash AS m_chash_bytes, b.b_model AS m_model, n.n_topic_id AS m_topic_id, (1 - n.n_dist)::double precision AS m_sim FROM batch b CROSS JOIN LATERAL ( SELECT ct.topic_id AS n_topic_id, (ct.embedding_768 OPERATOR(nexus.<=>) b.b_emb) AS n_dist FROM nexus.taxonomy_centroids ct WHERE ct.embedding_model = p_embedding_model AND ct.tenant_id = p_tenant AND (CASE WHEN ct.collection_id IS NOT NULL AND v_cid IS NOT NULL THEN ct.collection_id <> v_cid ELSE ct.collection <> p_collection END) AND (ct.collection_id IS NULL OR ct.collection_id <> ALL (ARRAY( SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant AND cc.embedding_model = p_embedding_model AND (cc.superseded_by_id IS NOT NULL OR COALESCE(cc.superseded_by, '') <> '')))) AND (ct.collection_id IS NOT NULL OR ct.collection <> ALL (ARRAY( SELECT cc.name FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant AND cc.embedding_model = p_embedding_model AND (cc.superseded_by_id IS NOT NULL OR COALESCE(cc.superseded_by, '') <> '') AND cc.name <> ''))) AND ct.embedding_768 IS NOT NULL ORDER BY ct.embedding_768 OPERATOR(nexus.<=>) b.b_emb, ct.topic_id ASC LIMIT 1 ) n ), persisted AS ( -- RDR-225: embedding_model is the chunk's own (it is part of the four-column chunk foreign key). INSERT INTO nexus.topic_assignments AS ta (tenant_id, doc_id, topic_id, assigned_by, similarity, assigned_at, source_collection, embedding_model, source_collection_id) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'projection', n.m_sim, now(), p_collection, n.m_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = current_setting('nexus.tenant', true) AND cc.name = p_collection) FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO UPDATE SET similarity = GREATEST(COALESCE(ta.similarity, -1.0), EXCLUDED.similarity), assigned_at = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.assigned_at ELSE ta.assigned_at END, source_collection = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection ELSE ta.source_collection END, -- the model moves with the source collection: the pair is one chunk reference. embedding_model = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.embedding_model ELSE ta.embedding_model END, -- the id moves with the name; a row the name did not move keeps its id, or takes the registry's if it has none source_collection_id = CASE WHEN EXCLUDED.similarity > COALESCE(ta.similarity, -1.0) THEN EXCLUDED.source_collection_id ELSE COALESCE(ta.source_collection_id, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = current_setting('nexus.tenant', true) AND cc.name = ta.source_collection)) END, assigned_by = 'projection' RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, n.m_sim FROM nearest n; ELSE RETURN QUERY WITH nearest AS ( SELECT DISTINCT ON (c.chash) encode(c.chash, 'hex') AS m_chash, c.chash AS m_chash_bytes, c.embedding_model AS m_model, ct.topic_id AS m_topic_id, (1 - (c.embedding_768 OPERATOR(nexus.<=>) ct.embedding_768))::double precision AS m_sim FROM nexus.chunks c JOIN nexus.taxonomy_centroids ct ON ct.embedding_model = p_embedding_model AND ct.tenant_id = p_tenant AND (ct.collection_id = v_cid OR (ct.collection_id IS NULL AND ct.collection = p_collection AND p_collection <> '')) AND ct.embedding_768 IS NOT NULL WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND (c.collection_id = v_cid OR (c.collection_id IS NULL AND c.collection = p_collection AND p_collection <> '')) AND c.embedding_768 IS NOT NULL AND c.chash = ANY(ARRAY(SELECT decode(x, 'hex') FROM unnest(p_chashes) x)) ORDER BY c.chash, (c.embedding_768 OPERATOR(nexus.<=>) ct.embedding_768) ASC, ct.topic_id ASC ), persisted AS ( INSERT INTO nexus.topic_assignments (tenant_id, doc_id, topic_id, assigned_by, source_collection, embedding_model, source_collection_id) SELECT current_setting('nexus.tenant', true), n.m_chash_bytes, n.m_topic_id, 'centroid', p_collection, n.m_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = current_setting('nexus.tenant', true) AND cc.name = p_collection) FROM nearest n ON CONFLICT (tenant_id, doc_id, topic_id) DO NOTHING RETURNING 1 ) SELECT n.m_chash, n.m_topic_id, NULL::double precision FROM nearest n; END IF; END; $function$;

