    dim                      int,
    p_tenant_id              text,
    p_quarantine_collection  text,
    p_origin_collection      text,
    p_cutoff                 text,
    p_floor_fraction         float8,
    p_floor_min_chunks       int,
    p_force                  boolean
)
RETURNS TABLE(expired bigint, refused bigint)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_mine      bigint;
    v_chashes   bytea[];
    v_protected bytea[];
    v_expired   bigint;
    v_refused   bigint;
    v_frac      float8;
BEGIN
    IF dim NOT IN (384, 768, 1024) THEN
        RAISE EXCEPTION
            'gc_expire_quarantine: unsupported dim %. Supported values: 384, 768, 1024',
            dim;
    END IF;

    SELECT count(*),
           array_agg(c.chash) FILTER (
               WHERE COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                 AND NOT EXISTS (
                       SELECT 1 FROM nexus.catalog_document_chunks m
                        WHERE m.tenant_id  = c.tenant_id
                          AND m.collection = p_origin_collection
                          AND m.chash      = c.chash
                     )),
           array_agg(c.chash) FILTER (
               WHERE COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
                 AND EXISTS (
                       SELECT 1 FROM nexus.catalog_document_chunks m
                        WHERE m.tenant_id  = c.tenant_id
                          AND m.collection = p_origin_collection
                          AND m.chash      = c.chash
                     ))
      INTO v_mine, v_chashes, v_protected
      FROM nexus.chunks c
     WHERE c.tenant_id  = p_tenant_id
       AND c.collection = p_quarantine_collection
       AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection
       -- Skip the rows tagged quarantined_by = 'engine-reaper' (nexus.reaper_owns_quarantined_row, vectors-024-2):
       -- the engine's own rows are expired by nexus.reaper_expire_quarantine, never here. This comment keeps the
       -- literal in the function's stored body (prosrc) as a TRANSITION SHIM for conexus's existing deploy census,
       -- which matches on it; the census should read pg_proc for nexus.reaper_owns_quarantined_row instead, and the
       -- comment can go once it does. It is not the contract: the contract is the call below.
       AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE;

    v_expired := COALESCE(array_length(v_chashes, 1), 0);
    v_refused := COALESCE(array_length(v_protected, 1), 0);

    IF v_expired = 0 THEN
        RETURN QUERY SELECT 0::bigint, v_refused;
        RETURN;
    END IF;

    v_frac := v_expired::float8 / v_mine::float8;
    IF v_expired >= p_floor_min_chunks AND v_frac > p_floor_fraction AND NOT p_force THEN
        RETURN QUERY SELECT 0::bigint, v_expired + v_refused;
        RETURN;
    END IF;

    -- The ownership exclusion is repeated here: a row the reaper re-moved (a fresh tag) between the read above
    -- and this delete is the engine's now, and is not taken.
    -- What is reported and audited is what this DELETE really removed (RETURNING), not what the read above chose:
    -- a row the reaper re-moved in between is not counted.
    WITH del AS (
        DELETE FROM nexus.chunks c
         WHERE c.tenant_id = p_tenant_id AND c.collection = p_quarantine_collection
           AND c.chash = ANY(v_chashes)
           AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE
        RETURNING c.chash
    )
    SELECT COALESCE(array_agg(d.chash ORDER BY d.chash), '{}'::bytea[]) INTO v_chashes FROM del d;
    v_expired := COALESCE(array_length(v_chashes, 1), 0);

    -- nexus-sybbh: the audit row in the SAME transaction as the delete (catalog-033-3); truncated at 5000 chashes.
    IF v_expired > 0 THEN
        INSERT INTO nexus.gc_audit
            (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details)
        VALUES (
            p_tenant_id, 'gc_expire_quarantine', p_quarantine_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection), 'engine', false, v_expired,
            COALESCE(
                (SELECT jsonb_agg(encode(x, 'hex'))
                   FROM unnest(v_chashes[1:LEAST(v_expired, 5000)]) x),
                '[]'::jsonb),
            jsonb_build_object('origin_collection', p_origin_collection, 'refused', v_refused, 'cutoff', p_cutoff)
                || CASE WHEN v_expired > 5000
                        THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000)
                        ELSE '{}'::jsonb END
        );
    END IF;

    RETURN QUERY SELECT v_expired, v_refused;
END;
$$;

changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.gc_expire_quarantine_bounded(
    dim                      int,
    p_tenant_id              text,
    p_quarantine_collection  text,
    p_origin_collection      text,
    p_cutoff                 text,
    p_floor_fraction         float8,
    p_floor_min_chunks       int,
    p_force                  boolean,
    p_row_limit              int,
    p_count_refused          boolean
)
RETURNS TABLE(expired bigint, refused bigint, more boolean, floor_refused boolean)
LANGUAGE plpgsql
SECURITY INVOKER
AS $$
DECLARE
    v_origin_id bigint;
    v_quar_id bigint;
    v_row_limit  int;
    v_mine       bigint;
    v_eligible   bigint;
    v_protected  bigint;
    v_refused    bigint;
    v_probe      bytea[];
    v_victims    bytea[];
    v_deleted    bytea[];
    v_rows       bigint := 0::bigint;
    v_more       boolean := false;
BEGIN
    SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection;
    SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection;
    IF dim NOT IN (384, 768, 1024) THEN
        RAISE EXCEPTION
            'gc_expire_quarantine_bounded: unsupported dim %. Supported values: 384, 768, 1024',
            dim;
    END IF;

    -- A non-positive bound is a caller error, not "unbounded": the point of this function is the bound.
    IF COALESCE(p_row_limit, 0) <= 0 THEN
        RAISE EXCEPTION
            'gc_expire_quarantine_bounded: p_row_limit must be positive, got %. Use nexus.gc_expire_quarantine for the unbounded expiry.',
            p_row_limit
            USING ERRCODE = 'invalid_parameter_value';
    END IF;

    -- 5,000 is gc_audit's chash ceiling (CatalogRepository.GC_AUDIT_MAX_CHASHES): a page never deletes more
    -- distinct chashes than its audit row can list.
    v_row_limit := LEAST(p_row_limit, 5000);

    PERFORM set_config('lock_timeout', '2000', true);
    PERFORM set_config('statement_timeout', '25000', true);
    BEGIN
        PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_quarantine_collection));
    EXCEPTION
        WHEN lock_not_available THEN
            RAISE EXCEPTION
                'gc_expire_quarantine_bounded: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- another expiry page holds it, OR your own previous bounded call is still committing after the edge cut you. Poll pg_stat_activity for an active expiry on this collection before retrying; a fixed sleep builds a lock convoy.',
                p_tenant_id, p_quarantine_collection
                USING ERRCODE = 'lock_not_available';
    END;

    IF p_floor_fraction < 1 AND NOT COALESCE(p_force, false) THEN
        SELECT count(*),
               count(*) FILTER (WHERE s.past AND NOT s.referenced),
               count(*) FILTER (WHERE s.past AND s.referenced)
          INTO v_mine, v_eligible, v_protected
          FROM (
            SELECT COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff AS past,
                   EXISTS (
                     SELECT 1 FROM nexus.catalog_document_chunks m
                      WHERE m.tenant_id  = c.tenant_id
                        AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> ''))
                        AND m.chash      = c.chash
                   ) AS referenced
              FROM nexus.chunks c
             WHERE c.tenant_id  = p_tenant_id
               AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> ''))
               AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection
               AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE
          ) s;

        IF v_eligible > 0 AND v_eligible >= p_floor_min_chunks
           AND v_eligible::float8 / v_mine::float8 > p_floor_fraction THEN
            -- Whole refusal: nothing deleted, no audit row; refused keeps the unbounded form's meaning.
            RETURN QUERY SELECT 0::bigint, v_eligible + v_protected, true, true;
            RETURN;
        END IF;
        v_refused := v_protected;
    ELSIF p_count_refused THEN
        SELECT count(*) INTO v_refused
          FROM nexus.chunks c
         WHERE c.tenant_id  = p_tenant_id
           AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> ''))
           AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection
           AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE
           AND COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
           AND EXISTS (
                 SELECT 1 FROM nexus.catalog_document_chunks m
                  WHERE m.tenant_id  = c.tenant_id
                    AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> ''))
                    AND m.chash      = c.chash
               );
    END IF;

    -- THE VICTIMS, selected from live state in chash order. The probe takes one past the page to answer `more`.
    -- The eligibility predicate is in the WHERE, ahead of the LIMIT.
    SELECT array_agg(x.chash ORDER BY x.chash) INTO v_probe
      FROM (
        SELECT DISTINCT c.chash
          FROM nexus.chunks c
         WHERE c.tenant_id  = p_tenant_id
           AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> ''))
           AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection
           AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE
           AND COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
           AND NOT EXISTS (
                 SELECT 1 FROM nexus.catalog_document_chunks m
                  WHERE m.tenant_id  = c.tenant_id
                    AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> ''))
                    AND m.chash      = c.chash
               )
         ORDER BY c.chash
         LIMIT v_row_limit + 1
      ) x;

    IF v_probe IS NULL THEN
        RETURN QUERY SELECT 0::bigint, v_refused, false, false;
        RETURN;
    END IF;

    v_more := array_length(v_probe, 1) > v_row_limit;
    v_victims := CASE WHEN v_more THEN v_probe[1:v_row_limit] ELSE v_probe END;

    -- Every eligibility predicate is restated: a row that changed and committed while this DELETE waited on its
    -- row lock is re-checked against its new version (READ COMMITTED), so it is not deleted if it no longer
    -- qualifies. What is reported and audited is what this DELETE really removed.
    WITH del AS (
        DELETE FROM nexus.chunks c
         WHERE c.tenant_id  = p_tenant_id
           AND (c.collection_id = v_quar_id OR (c.collection_id IS NULL AND c.collection = p_quarantine_collection AND p_quarantine_collection <> ''))
           AND c.chash = ANY(v_victims)
           AND COALESCE(c.metadata->>'origin_collection', p_origin_collection) = p_origin_collection
           AND nexus.reaper_owns_quarantined_row(c.metadata) IS NOT TRUE
           AND COALESCE(c.metadata->>'quarantined_at', '9999-12-31T23:59:59Z') <= p_cutoff
           AND NOT EXISTS (
                 SELECT 1 FROM nexus.catalog_document_chunks m
                  WHERE m.tenant_id  = c.tenant_id
                    AND (m.collection_id = v_origin_id OR (m.collection_id IS NULL AND m.collection = p_origin_collection AND p_origin_collection <> ''))
                    AND m.chash      = c.chash
               )
        RETURNING c.chash
    )
    SELECT count(*), array_agg(DISTINCT d.chash ORDER BY d.chash)
      INTO v_rows, v_deleted
      FROM del d;

    -- One audit row per page that deleted anything, in the same transaction as the delete. At most 5,000 distinct
    -- chashes by the clamp, so the list is never truncated.
    IF v_rows > 0 THEN
        INSERT INTO nexus.gc_audit
            (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details)
        VALUES (
            p_tenant_id, 'gc_expire_quarantine_bounded', p_quarantine_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection), 'engine', false,
            array_length(v_deleted, 1),
            COALESCE(
                (SELECT jsonb_agg(encode(x, 'hex') ORDER BY x) FROM unnest(v_deleted) x),
                '[]'::jsonb),
            jsonb_build_object(
                'origin_collection', p_origin_collection,
                'cutoff', p_cutoff,
                'row_limit', v_row_limit,
                'rows', v_rows,
                'more_after', v_more)
                || CASE WHEN v_refused IS NOT NULL
                        THEN jsonb_build_object('refused', v_refused)
                        ELSE '{}'::jsonb END
        );
    END IF;

    RETURN QUERY SELECT v_rows, v_refused, v_more, false;
END;
$$;

