 embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, created_at = EXCLUDED.created_at, collection_id = EXCLUDED.collection_id; EXIT; EXCEPTION WHEN unique_violation THEN GET STACKED DIAGNOSTICS v_p35b_con = CONSTRAINT_NAME; IF v_p35b_try = 2 OR NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_class ic JOIN pg_catalog.pg_namespace ns ON ns.oid = ic.relnamespace JOIN pg_catalog.pg_index ix ON ix.indexrelid = ic.oid WHERE ns.nspname = 'nexus' AND ic.relname = v_p35b_con AND ix.indisunique AND coalesce(pg_catalog.pg_partition_root(ix.indrelid), ix.indrelid) = 'nexus.chunks'::regclass AND (SELECT pg_catalog.array_agg(a.attname::text ORDER BY a.attname) FROM pg_catalog.pg_attribute a WHERE a.attrelid = ix.indrelid AND a.attnum = ANY (ix.indkey)) = ARRAY['chash', 'collection_id', 'embedding_model', 'tenant_id']) THEN RAISE; END IF; END; END LOOP;
