CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans_floored( dim int, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit int, p_row_limit int, p_floor_fraction float8, p_floor_min_chunks int, p_force boolean, p_quarantine_expires_at text DEFAULT NULL ) RETURNS TABLE(moved bigint, sample jsonb, remaining bigint, refused boolean, reapable_count bigint, total_count bigint) LANGUAGE plpgsql SECURITY INVOKER AS $$ DECLARE v_origin_id bigint; v_quar_id bigint; v_reapable bigint; v_total bigint; v_moved bigint; v_sample jsonb; v_remaining bigint; v_repeat boolean; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection; IF p_row_limit IS NOT NULL AND p_row_limit <= 0 THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: p_row_limit must be positive when given (NULL selects the unbounded sweep), got %', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
IF p_floor_fraction IS NOT NULL AND ( p_floor_fraction < 0 OR p_floor_fraction > 1 OR p_floor_min_chunks IS NULL OR p_floor_min_chunks < 0) THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: the floor must be a fraction in [0, 1] and a non-negative minimum, got % / %', p_floor_fraction, p_floor_min_chunks USING ERRCODE = 'invalid_parameter_value'; END IF;
-- The stamp is compared as text with other fixed-width stamps (reaper_expire_client_quarantine), so it must be -- that shape: any other shape could sort before now() by accident and expire a row early. IF p_quarantine_expires_at IS NOT NULL AND p_quarantine_expires_at !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$' THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: p_quarantine_expires_at must be yyyy-MM-ddTHH:mm:ssZ, got %', p_quarantine_expires_at USING ERRCODE = 'invalid_parameter_value'; END IF;
