-- The judgement. Only when a floor was given and the caller did not override it. IF p_floor_fraction IS NOT NULL AND NOT COALESCE(p_force, false) THEN PERFORM set_config('lock_timeout', '2000', true); BEGIN PERFORM pg_advisory_xact_lock(hashtext('sweepgate:' || p_tenant_id || '/' || p_collection)); EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION 'gc_quarantine_orphans_floored: timed out acquiring the RDR-191 sweep gate for tenant=%, collection=% -- a manifest writer is holding it; retry', p_tenant_id, p_collection USING ERRCODE = 'lock_not_available'; END;
-- Counted UNDER the gate, on the whole collection: the reapable set is the numerator, every -- stored chunk the denominator (the reaper's reading, vectors-024-1). SELECT count(*), count(*) FILTER (WHERE EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL))) INTO v_total, v_reapable FROM nexus.chunks c WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection;
IF v_reapable >= p_floor_min_chunks AND v_total > 0 AND v_reapable::float8 / v_total::float8 > p_floor_fraction THEN -- One row per STATE, not per call: skip the INSERT when the newest refusal row of this -- (tenant, collection) carries identical counts and floor values and is under an hour old. -- Every `nx index repo` walk repeats the same refusal for a collection that stays over the -- floor, and gc_audit has no retention. The refusal is still returned either way. SELECT EXISTS ( SELECT 1 FROM ( SELECT a.details, a.created_at FROM nexus.gc_audit a WHERE a.tenant_id = p_tenant_id AND a.collection = p_collection AND a.operation = 'gc_quarantine_orphans_refused' ORDER BY a.id DESC LIMIT 1) last WHERE last.created_at > now() - interval '1 hour' AND (last.details->>'reapable_count')::bigint = v_reapable AND (last.details->>'total_count')::bigint = v_total AND (last.details->>'floor_fraction')::float8 = p_floor_fraction AND (last.details->>'floor_min_chunks')::int = p_floor_min_chunks) INTO v_repeat; IF NOT v_repeat THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, collection_id, actor, dry_run, chash_count, chashes, details) VALUES ( p_tenant_id, 'gc_quarantine_orphans_refused', p_collection, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_collection), 'engine', false, 0, '[]'::jsonb, jsonb_build_object( 'reason', 'FLOOR', 'form', CASE WHEN p_row_limit IS NULL THEN 'unbounded' ELSE 'bounded' END, 'quarantine_collection', p_quarantine_collection, 'reapable_count', v_reapable, 'total_count', v_total, 'floor_fraction', p_floor_fraction, 'floor_min_chunks', p_floor_min_chunks)); END IF; RETURN QUERY SELECT 0::bigint, NULL::jsonb, v_reapable, true, v_reapable, v_total; RETURN; END IF; END IF;
-- The move. The existing functions take the same gate (already ours on the judged path), choose their -- victim set once, and write their own audit row. IF p_row_limit IS NULL THEN SELECT g.moved, g.sample INTO v_moved, v_sample FROM nexus.gc_quarantine_orphans( dim, p_tenant_id, p_collection, p_quarantine_collection, p_quarantined_at, p_sample_limit) g; v_remaining := NULL; ELSE SELECT g.moved, g.sample, g.remaining INTO v_moved, v_sample, v_remaining FROM nexus.gc_quarantine_orphans_bounded( dim, p_tenant_id, p_collection, p_quarantine_collection, p_quarantined_at, p_sample_limit, p_row_limit) g; END IF;
-- nexus-alsq3: the client's retention, written on the rows THIS call moved. The base functions are not -- touched, but each leaves the victim set it chose in a temp table that lives to the end of the transaction -- (_wbfpw16_victim in the unbounded form, _a6mon_victim in the bounded one; both ON COMMIT DROP, both refilled -- by every call, so what the wrapper reads is this call's set). The UPDATE joins those chashes, so it is a -- primary-key probe per moved row and never a scan of the quarantine sibling by metadata: a drain of N batches -- over a sibling of M rows costs N x batch, not N x M. A re-moved chash was rewritten by the base function's -- ON CONFLICT DO UPDATE, which carries no stamp, so a stale one cannot survive; a row already in the sibling -- from another call or another batch is not in this call's set and is not touched. Same transaction as the -- move, under the same sweep gate. A victim whose DELETE lost the last-write recheck stays live but its copy is -- already in the sibling carrying this call's quarantined_at, so it is stamped like the rest. -- The statement is dynamic because the temp table does not exist until the base function runs: a static -- reference is an error to plpgsql_check (PlpgsqlCheckGateTest holds every routine outside vectors-030 to no -- errors). The table name is one of two constants, never caller text; the values go through USING. IF p_quarantine_expires_at IS NOT NULL AND COALESCE(v_moved, 0) > 0 THEN EXECUTE format( 'UPDATE nexus.chunks c SET metadata = COALESCE(c.metadata, ''{}''::jsonb) || jsonb_build_object(''quarantine_expires_at'', $1), collection_id = COALESCE(c.collection_id, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = c.tenant_id AND cc.name = c.collection)) FROM %I v WHERE c.tenant_id = $2 AND c.collection = $3 AND c.chash = v.chash', CASE WHEN p_row_limit IS NULL THEN '_wbfpw16_victim' ELSE '_a6mon_victim' END) USING p_quarantine_expires_at, p_tenant_id, p_quarantine_collection; END IF;
RETURN QUERY SELECT v_moved, v_sample, v_remaining, false, v_reapable, v_total; END; $$;

