CREATE OR REPLACE FUNCTION nexus.gc_restore_rereferenced_bounded(dim integer, p_tenant_id text, p_quarantine_collection text, p_origin_collection text, p_row_limit integer) RETURNS TABLE(restored bigint, remaining bigint) LANGUAGE plpgsql AS $function$ DECLARE v_origin_id bigint; v_quar_id bigint; v_chashes bytea[]; v_restored bigint := 0; v_remaining bigint := 0; v_row_limit int; v_row_count bigint := 0; v_collision_count bigint; v_collision_sample text[]; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN SELECT cc.collection_id INTO v_origin_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_origin_collection; SELECT cc.collection_id INTO v_quar_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection; IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- A non-positive bound is a caller error, not "unbounded". The whole -- point of this function is the bound; silently removing it would hand -- back the exact unbounded transaction this exists to prevent (mirrors -- catalog-037's identical guard). IF COALESCE(p_row_limit, 0) <= 0 THEN RAISE EXCEPTION 'gc_restore_rereferenced_bounded: p_row_limit must be positive, got %. Use nexus.gc_restore_rereferenced for the unbounded restore.', p_row_limit USING ERRCODE = 'invalid_parameter_value'; END IF;
v_row_limit := LEAST(p_row_limit, 100000);
