CREATE OR REPLACE FUNCTION nexus.stamp_chunks_on_manifest_update() RETURNS trigger LANGUAGE plpgsql AS $function$ DECLARE v_p35b_con text; -- the constraint of a unique_violation, for the retry on the id twin BEGIN -- The keys the statement dropped are the old keys minus the new keys: a row that keeps its -- (tenant, collection, chash), whatever else changed, drops nothing; one that moves position and -- chash together drops the old chash. Same lock, same upsert, same guard as the DELETE trigger. PERFORM 1 FROM nexus.chunks c JOIN (SELECT o0.tenant_id, o0.collection, o0.chash, o0.embedding_model, max(o0.collection_id) AS collection_id FROM old_rows o0 WHERE NOT EXISTS (SELECT 1 FROM new_rows n0 WHERE n0.tenant_id = o0.tenant_id AND n0.chash = o0.chash AND n0.embedding_model = o0.embedding_model AND (n0.collection_id = o0.collection_id OR ((n0.collection_id IS NULL OR o0.collection_id IS NULL) AND n0.collection = o0.collection AND n0.collection <> ''))) GROUP BY o0.tenant_id, o0.collection, o0.chash, o0.embedding_model) o ON o.tenant_id = c.tenant_id AND (o.collection_id = c.collection_id OR ((o.collection_id IS NULL OR c.collection_id IS NULL) AND o.collection = c.collection AND o.collection <> '')) AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash FOR NO KEY UPDATE OF c;
-- The record rows of every key this statement touches, the dropped keys (upserted below) and the added keys -- (deleted below), locked in ONE key-ordered pass before either, so two UPDATE statements that swap keys -- take their record rows in the same total order. The chunk rows come first, as in the DELETE trigger. PERFORM 1 FROM nexus.chunk_orphaned_at q JOIN (SELECT o0.tenant_id, o0.collection, o0.chash, max(o0.collection_id) AS collection_id FROM old_rows o0 WHERE NOT EXISTS (SELECT 1 FROM new_rows n0 WHERE n0.tenant_id = o0.tenant_id AND n0.chash = o0.chash AND (n0.collection_id = o0.collection_id OR ((n0.collection_id IS NULL OR o0.collection_id IS NULL) AND n0.collection = o0.collection AND n0.collection <> ''))) GROUP BY o0.tenant_id, o0.collection, o0.chash UNION SELECT n1.tenant_id, n1.collection, n1.chash, max(n1.collection_id) AS collection_id FROM new_rows n1 WHERE NOT EXISTS (SELECT 1 FROM old_rows o1 WHERE o1.tenant_id = n1.tenant_id AND o1.chash = n1.chash AND (o1.collection_id = n1.collection_id OR ((o1.collection_id IS NULL OR n1.collection_id IS NULL) AND o1.collection = n1.collection AND o1.collection <> ''))) GROUP BY n1.tenant_id, n1.collection, n1.chash) k ON k.tenant_id = q.tenant_id AND (k.collection_id = q.collection_id OR ((k.collection_id IS NULL OR q.collection_id IS NULL) AND k.collection = q.collection AND k.collection <> '')) AND k.chash = q.chash ORDER BY q.tenant_id, q.collection, q.chash FOR UPDATE OF q;
-- two unique keys on nexus.chunk_orphaned_at once P3.4 builds its id twin (idx_chunk_orphaned_at_id_chash_uq): the ON -- CONFLICT arbiter absorbs a race on itself only, so a racing writer's row can trip the twin as a plain 23505. Retry once -- when the 23505 is that twin (a unique index on chunk_orphaned_at over the id key's columns); anything else is raised. FOR v_p35b_try IN 1 .. 2 LOOP BEGIN -- RDR-225: carries the chunk's embedding_model; the arbiter stays the table's own three-column key. INSERT INTO nexus.chunk_orphaned_at AS q (tenant_id, collection, chash, orphaned_at, embedding_model, collection_id) SELECT c.tenant_id, c.collection, c.chash, now(), c.embedding_model, COALESCE(c.collection_id, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = c.tenant_id AND cc.name = c.collection)) FROM nexus.chunks c JOIN (SELECT o0.tenant_id, o0.collection, o0.chash, o0.embedding_model, max(o0.collection_id) AS collection_id FROM old_rows o0 WHERE NOT EXISTS (SELECT 1 FROM new_rows n0 WHERE n0.tenant_id = o0.tenant_id AND n0.chash = o0.chash AND n0.embedding_model = o0.embedding_model AND (n0.collection_id = o0.collection_id OR ((n0.collection_id IS NULL OR o0.collection_id IS NULL) AND n0.collection = o0.collection AND n0.collection <> ''))) GROUP BY o0.tenant_id, o0.collection, o0.chash, o0.embedding_model) o ON o.tenant_id = c.tenant_id AND (o.collection_id = c.collection_id OR ((o.collection_id IS NULL OR c.collection_id IS NULL) AND o.collection = c.collection AND o.collection <> '')) AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET orphaned_at = EXCLUDED.orphaned_at, collection_id = EXCLUDED.collection_id WHERE q.orphaned_at < now() - interval '1 hour'; EXIT; EXCEPTION WHEN unique_violation THEN GET STACKED DIAGNOSTICS v_p35b_con = CONSTRAINT_NAME; IF v_p35b_try = 2 OR NOT EXISTS ( SELECT 1 FROM pg_catalog.pg_class ic JOI