CREATE OR REPLACE FUNCTION nexus.stamp_chunks_on_manifest_update() RETURNS trigger LANGUAGE plpgsql AS $function$ BEGIN -- The keys the statement dropped are the old keys minus the new keys: a row that keeps its -- (tenant, collection, chash), whatever else changed, drops nothing; one that moves position and -- chash together drops the old chash. Same lock, same upsert, same guard as the DELETE trigger. PERFORM 1 FROM nexus.chunks c JOIN (SELECT tenant_id, collection, chash, embedding_model FROM old_rows EXCEPT SELECT tenant_id, collection, chash, embedding_model FROM new_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash FOR NO KEY UPDATE OF c;
-- The record rows of every key this statement touches, the dropped keys (upserted below) and the added keys -- (deleted below), locked in ONE key-ordered pass before either, so two UPDATE statements that swap keys -- take their record rows in the same total order. The chunk rows come first, as in the DELETE trigger. PERFORM 1 FROM nexus.chunk_orphaned_at q JOIN ((SELECT tenant_id, collection, chash FROM old_rows EXCEPT SELECT tenant_id, collection, chash FROM new_rows) UNION (SELECT tenant_id, collection, chash FROM new_rows EXCEPT SELECT tenant_id, collection, chash FROM old_rows)) k ON k.tenant_id = q.tenant_id AND k.collection = q.collection AND k.chash = q.chash ORDER BY q.tenant_id, q.collection, q.chash FOR UPDATE OF q;
-- RDR-225: carries the chunk's embedding_model; the arbiter stays the table's own three-column key. INSERT INTO nexus.chunk_orphaned_at AS q (tenant_id, collection, chash, orphaned_at, embedding_model, collection_id) SELECT c.tenant_id, c.collection, c.chash, now(), c.embedding_model, COALESCE(c.collection_id, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = c.tenant_id AND cc.name = c.collection)) FROM nexus.chunks c JOIN (SELECT tenant_id, collection, chash, embedding_model FROM old_rows EXCEPT SELECT tenant_id, collection, chash, embedding_model FROM new_rows) o ON o.tenant_id = c.tenant_id AND o.collection = c.collection AND o.chash = c.chash AND o.embedding_model = c.embedding_model ORDER BY c.tenant_id, c.collection, c.chash ON CONFLICT (tenant_id, collection, chash) DO UPDATE SET orphaned_at = EXCLUDED.orphaned_at, collection_id = EXCLUDED.collection_id WHERE q.orphaned_at < now() - interval '1 hour';
-- A chunk this statement gave an owner (a key of new_rows not in old_rows) carries no record. DELETE FROM nexus.chunk_orphaned_at q USING (SELECT tenant_id, collection, chash FROM new_rows EXCEPT SELECT tenant_id, collection, chash FROM old_rows) n WHERE n.tenant_id = q.tenant_id AND n.collection = q.collection AND n.chash = q.chash; RETURN NULL; END; $function$;

