CREATE OR REPLACE FUNCTION nexus.chash_conformance_report(dim int) RETURNS TABLE( table_name text, total bigint, non_conformant bigint, sample_chashes text[] ) LANGUAGE plpgsql SECURITY INVOKER AS $$ BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'chash_conformance_report: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
-- Line 1: the chunk table's rows at this width (embedding_<dim> IS NOT NULL). Reads no name. The label stays -- 'nexus.chunks_<dim>' for report consumers although it no longer names a real relation. IF dim = 384 THEN RETURN QUERY SELECT 'nexus.chunks_384'::text, (SELECT count(*) FROM nexus.chunks WHERE embedding_384 IS NOT NULL)::bigint, (SELECT count(*) FROM nexus.chunks WHERE embedding_384 IS NOT NULL AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks WHERE embedding_384 IS NOT NULL AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); ELSIF dim = 768 THEN RETURN QUERY SELECT 'nexus.chunks_768'::text, (SELECT count(*) FROM nexus.chunks WHERE embedding_768 IS NOT NULL)::bigint, (SELECT count(*) FROM nexus.chunks WHERE embedding_768 IS NOT NULL AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks WHERE embedding_768 IS NOT NULL AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); ELSE RETURN QUERY SELECT 'nexus.chunks_1024'::text, (SELECT count(*) FROM nexus.chunks WHERE embedding_1024 IS NOT NULL)::bigint, (SELECT count(*) FROM nexus.chunks WHERE embedding_1024 IS NOT NULL AND octet_length(chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(chash, 'hex') ORDER BY chash) FROM (SELECT chash FROM nexus.chunks WHERE embedding_1024 IS NOT NULL AND octet_length(chash) <> 32 ORDER BY chash LIMIT 20) s), '{}'::text[]); END IF;
-- Line 2: the manifest rows whose collection's catalog row registers a model of this dimension. The model is -- the ROW's (catalog_collections.embedding_model, joined to embedding_models for its dimension), never a token -- parsed out of the collection name: a collection under any label is counted at the width its row says. RETURN QUERY WITH m AS ( SELECT c.chash FROM nexus.catalog_document_chunks c JOIN nexus.catalog_collections cc ON cc.tenant_id = c.tenant_id AND cc.name = c.collection JOIN nexus.embedding_models em ON em.embedding_model = cc.embedding_model AND em.dimension = chash_conformance_report.dim WHERE c.collection IS NOT NULL ) SELECT 'nexus.catalog_document_chunks'::text, (SELECT count(*) FROM m)::bigint, (SELECT count(*) FROM m WHERE octet_length(m.chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(s.chash, 'hex') ORDER BY s.chash) FROM (SELECT m.chash FROM m WHERE octet_length(m.chash) <> 32 ORDER BY m.chash LIMIT 20) s), '{}'::text[]);
-- Line 3, only when it has rows: the manifest rows whose collection has NO catalog row (a legacy name nothing -- registered). With no row there is no registered model, and the name is not read, so these rows get their own -- line instead of a guess; the line carries the rows whose own embedding_model column is a model of this -- dimension, so the per-line totals sum to what the name-parsing report counted. A collection with a row is -- never on this line; a store with no such rows has no such line. RETURN QUERY WITH r AS ( SELECT c.chash FROM nexus.catalog_document_chunks c JOIN nexus.embedding_models em ON em.embedding_model = c.embedding_model AND em.dimension = chash_conformance_report.dim WHERE c.collection IS NOT NULL AND NOT EXISTS (SELECT 1 FROM nexus.catalog_collections cc WHERE cc.tenant_id = c.tenant_id AND cc.name = c.collection) ) SELECT 'nexus.catalog_document_chunks (no catalog row)'::text, (SELECT count(*) FROM r)::bigint, (SELECT count(*) FROM r WHERE octet_length(r.chash) <> 32)::bigint, COALESCE( (SELECT array_agg(encode(s.chash, 'hex') ORDER BY s.chash) FROM (SELECT r.chash FROM r WHERE octet_length(r.chash) <> 32 ORDER BY r.chash LIMIT 20) s), '{}'::text[]) WHERE EXISTS (SELECT 1 FROM r); END; $$

