CREATE OR REPLACE FUNCTION nexus.gc_quarantine_orphans(dim integer, p_tenant_id text, p_collection text, p_quarantine_collection text, p_quarantined_at text, p_sample_limit integer) RETURNS TABLE(moved bigint, sample jsonb) LANGUAGE plpgsql AS $function$ DECLARE v_moved bigint; v_sample jsonb; v_collision_count bigint; v_collision_sample text[]; v_sample_limit int; v_origin_content_type text; v_origin_owner_id text; v_origin_embedding_model text; v_origin_model_version text; v_origin_dimension int; BEGIN IF dim NOT IN (384, 768, 1024) THEN RAISE EXCEPTION 'gc_quarantine_orphans: unsupported dim %. Supported values: 384, 768, 1024', dim; END IF;
