-- RDR-225: the row carries its own embedding_model (the quarantine sibling is registered under the -- origin's model just above, so the model is the same and the composite collection foreign key holds), -- and the arbiter is the four-column primary key of the partitioned table. INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, embedding_384, embedding_768, embedding_1024, metadata, embedding_model, collection_id) SELECT p_tenant_id, p_quarantine_collection, c.chash, c.chunk_text, c.embedding_384, c.embedding_768, c.embedding_1024, COALESCE(c.metadata, '{}'::jsonb) || jsonb_build_object('quarantined_at', p_quarantined_at, 'origin_collection', p_collection) || jsonb_strip_nulls(jsonb_build_object('origin_collection_id', (SELECT oc.collection_id FROM nexus.catalog_collections oc WHERE oc.tenant_id = p_tenant_id AND oc.name = p_collection))), c.embedding_model, (SELECT cc.collection_id FROM nexus.catalog_collections cc WHERE cc.tenant_id = p_tenant_id AND cc.name = p_quarantine_collection) FROM nexus.chunks c JOIN _wbfpw16_victim v ON v.chash = c.chash WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection ON CONFLICT (tenant_id, collection, chash, embedding_model) DO UPDATE SET chunk_text = EXCLUDED.chunk_text, embedding_384 = EXCLUDED.embedding_384, embedding_768 = EXCLUDED.embedding_768, embedding_1024 = EXCLUDED.embedding_1024, metadata = EXCLUDED.metadata, collection_id = EXCLUDED.collection_id;
WITH del AS ( DELETE FROM nexus.chunks c USING _wbfpw16_victim v WHERE c.tenant_id = p_tenant_id AND c.collection = p_collection AND c.chash = v.chash AND EXISTS (SELECT 1 FROM nexus.chunk_is_reapable( c.tenant_id, c.collection, c.chash, c.last_written_at, NULL)) RETURNING c.tenant_id, c.collection, c.chash, c.embedding_model, left(c.chunk_text, 80) AS text_prefix ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( SELECT jsonb_agg(jsonb_build_object('chash', encode(lim.chash, 'hex'), 'title', lim.title, 'text_prefix', lim.text_prefix)) AS s FROM (SELECT d.chash, d.text_prefix, (SELECT od.title FROM nexus.catalog_document_chunks oc JOIN nexus.catalog_documents od ON od.tenant_id = oc.tenant_id AND od.tumbler = oc.doc_id WHERE oc.tenant_id = d.tenant_id AND oc.chash = d.chash AND oc.embedding_model = d.embedding_model AND od.deleted_at IS NULL ORDER BY (oc.collection = d.collection) DESC, oc.doc_id LIMIT 1) AS title FROM del d LIMIT v_sample_limit) lim ) SELECT counted.n, sampled.s INTO v_moved, v_sample FROM counted, sampled;
