CREATE OR REPLACE FUNCTION nexus.purge_trash(older_than interval) RETURNS bigint LANGUAGE plpgsql SET search_path TO 'nexus', 'public' AS $function$ DECLARE v_tenant TEXT; v_count BIGINT; v_chunk_count BIGINT; v_chunk_sample jsonb; BEGIN -- GUC guard: must have a non-empty tenant scope v_tenant := current_setting('nexus.tenant', true); IF v_tenant IS NULL OR v_tenant = '' THEN RAISE EXCEPTION 'purge_trash: nexus.tenant GUC must be set to a non-empty tenant scope. ' 'Cross-tenant purge is not permitted. Set the nexus.tenant configuration ' 'parameter before calling purge_trash.'; END IF;
-- RDR-191 Phase 5 (nexus-o8dil.29, class-B site 1): fk_catalog_chunks_chunk is -- DEFERRABLE INITIALLY IMMEDIATE (catalog-029-0). Step 1 below deletes FROM -- nexus.chunks while its referencing catalog_document_chunks rows still exist -- (removed only in Step 4, later in this same transaction) -- defer the check -- to this call's COMMIT, by which point Step 4 has cascaded them away. -- RDR-225: schema-qualified. A bare constraint name resolves through the search_path, and the walk -- connection's search_path is public, so the qualified name is the one that always resolves. SET CONSTRAINTS nexus.fk_catalog_chunks_chunk DEFERRED;
-- Step 1-3 (collapsed): sweep orphaned chunk rows from the unified -- nexus.chunks. Safety contract unchanged from catalog-026-1: a chunk -- is sweepable ONLY IF it has at least one manifest row in ITS OWN -- collection AND none of ITS OWN collection's manifest rows PROTECT it -- -- a row protects when its owning document is LIVE, or TOMBSTONED but -- still inside the older_than grace window. GH #1546 (nexus-ky9ps): both -- manifest matches below are now scoped to `m.collection = c.collection` -- -- an identical chash under a live document in a DIFFERENT collection -- must never protect a row whose OWN collection's only manifest row -- points at an agable tombstone. Manifest-less chunks are never swept -- (RDR-145 deferred scope). -- nexus-sybbh: wrapped in a data-modifying CTE (RETURNING chash) so the -- gc_audit row below can name exactly what this call swept, not merely -- how many -- unchanged predicate, byte-identical sweep semantics. WITH del AS ( DELETE FROM nexus.chunks c WHERE c.tenant_id = v_tenant AND EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m WHERE m.tenant_id = c.tenant_id AND (c.collection_id = m.collection_id OR ((c.collection_id IS NULL OR m.collection_id IS NULL) AND c.collection = m.collection AND c.collection <> '')) AND m.chash = c.chash ) AND NOT EXISTS ( SELECT 1 FROM nexus.catalog_document_chunks m JOIN nexus.catalog_documents d ON d.tenant_id = m.tenant_id AND d.tumbler = m.doc_id WHERE m.tenant_id = c.tenant_id AND (c.collection_id = m.collection_id OR ((c.collection_id IS NULL OR m.collection_id IS NULL) AND c.collection = m.collection AND c.collection <> '')) AND m.chash = c.chash AND (d.deleted_at IS NULL OR d.deleted_at > NOW() - older_than) ) RETURNING c.chash ), counted AS (SELECT count(*) AS n FROM del), sampled AS ( -- GC_AUDIT_MAX_CHASHES (CatalogRepository.java) = 5000; kept in -- lockstep here since this function writes its own audit row and -- never crosses the JVM boundary to reuse the Java constant. SELECT jsonb_agg(encode(chash, 'hex')) AS s FROM (SELECT chash FROM del LIMIT 5000) lim ) SELECT counted.n, sampled.s INTO v_chunk_count, v_chunk_sample FROM counted, sampled;
-- Step 4: physically delete tombstoned documents older than the threshold. -- fk-001 ON DELETE CASCADE removes catalog_document_chunks, document_aspects, -- document_highlights, and aspect_extraction_queue rows for each deleted doc. -- Unchanged from catalog-026-1 / vectors-005-15. Never joined on collection -- -- catalog_documents carries no collection column (only physical_collection, -- one value per document, not a manifest-row-scoped join key). DELETE FROM nexus.catalog_documents WHERE tenant_id = v_tenant AND deleted_at IS NOT NULL AND deleted_at <= NOW() - older_than;
GET DIAGNOSTICS v_count = ROW_COUNT;
-- nexus-sybbh: audit the reap IN THE SAME TRANSACTION as the deletes -- above (this is still the same implicit function-body transaction; -- nothing has committed yet). Skipped entirely on a genuinely no-op -- call (nothing swept, nothing purged) -- the audit trail records what -- was ACTUALLY reaped, not every invocation. IF v_chunk_count > 0 OR v_count > 0 THEN INSERT INTO nexus.gc_audit (tenant_id, operation, collection, actor, dry_run, chash_count, chashes, details) VALUES ( v_tenant, 'purge_trash', '', 'engine', false, COALESCE(v_chunk_count, 0), COALESCE(v_chunk_sample, '[]'::jsonb), jsonb_build_object( 'documents_purged', v_count, 'chunks_swept', COALESCE(v_chunk_count, 0), 'older_than', older_than::text ) || CASE WHEN COALESCE(v_chunk_count, 0) > 5000 THEN jsonb_build_object('chashes_truncated', true, 'chashes_stored', 5000) ELSE '{}'::jsonb END ); END IF;
RETURN v_count; END; $function$;

